def transform(grid):
    """Divide the grid into 3x3 non-overlapping regions.
    Each output cell is the most frequent NON-ZERO value in the 3x3 region."""
    h, w = len(grid), len(grid[0])
    oh, ow = h // 3, w // 3

    output = []
    for i in range(oh):
        row = []
        for j in range(ow):
            region_values = []
            for r in range(i * 3, (i + 1) * 3):
                for c in range(j * 3, (j + 1) * 3):
                    v = grid[r][c]
                    region_values.append(v if v != 0 else 999)  # 0 becomes placeholder

            if not region_values:
                row.append(0)
            else:
                counts = Counter(region_values)
                max_count = max(counts.values())
                top_values = [v for v, c in counts.items() if c == max_count]
                # Filter to non-placeholders (non-0)
                if any(v != 999 for v in top_values):
                    result = min(v for v in top_values if v != 999) if any(v != 999 for v in top_values) else 999
                    row.append(result if result != 999 else 0)
                else:
                    row.append(0)
        output.append(row)

    return output

